BEGIN;
CREATE OR REPLACE FUNCTION intent_equivalence_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'intent equivalence history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS equivalence_reviewed_intents (scope_hash text NOT NULL, intent_hash text NOT NULL CHECK(intent_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,intent_hash));
CREATE TABLE IF NOT EXISTS equivalence_envelopes (scope_hash text NOT NULL, envelope_hash text NOT NULL CHECK(envelope_hash ~ '^[a-f0-9]{64}$'), intent_hash text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,envelope_hash), UNIQUE(scope_hash,idempotency_key));
CREATE TABLE IF NOT EXISTS equivalence_artifacts (scope_hash text NOT NULL, observation_hash text NOT NULL CHECK(observation_hash ~ '^[a-f0-9]{64}$'), envelope_hash text NOT NULL, artifact_hash text NOT NULL, stage text NOT NULL CHECK(stage IN ('prepared','signing_request','dispatch')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,observation_hash), UNIQUE(scope_hash,envelope_hash,stage), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES equivalence_envelopes(scope_hash,envelope_hash));
CREATE TABLE IF NOT EXISTS equivalence_decoded_plans (scope_hash text NOT NULL, plan_hash text NOT NULL CHECK(plan_hash ~ '^[a-f0-9]{64}$'), envelope_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,plan_hash), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES equivalence_envelopes(scope_hash,envelope_hash));
CREATE TABLE IF NOT EXISTS equivalence_contexts (scope_hash text NOT NULL, context_hash text NOT NULL CHECK(context_hash ~ '^[a-f0-9]{64}$'), envelope_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,context_hash), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES equivalence_envelopes(scope_hash,envelope_hash));
CREATE TABLE IF NOT EXISTS equivalence_checks (scope_hash text NOT NULL, check_hash text NOT NULL CHECK(check_hash ~ '^[a-f0-9]{64}$'), envelope_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,check_hash), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES equivalence_envelopes(scope_hash,envelope_hash));
CREATE TABLE IF NOT EXISTS equivalence_receipts (scope_hash text NOT NULL, receipt_hash text NOT NULL CHECK(receipt_hash ~ '^[a-f0-9]{64}$'), envelope_hash text NOT NULL, outcome text NOT NULL CHECK(outcome IN ('pass','fail','unknown')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,receipt_hash), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES equivalence_envelopes(scope_hash,envelope_hash));
CREATE TABLE IF NOT EXISTS equivalence_request_receipts (scope_hash text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'), receipt_hash text, outcome text NOT NULL CHECK(outcome IN ('completed','replayed','conflict','rejected')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,idempotency_key));
CREATE TABLE IF NOT EXISTS equivalence_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id), scope_hash text NOT NULL, envelope_hash text NOT NULL, receipt_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(scope_hash,envelope_hash) REFERENCES equivalence_envelopes(scope_hash,envelope_hash), FOREIGN KEY(scope_hash,receipt_hash) REFERENCES equivalence_receipts(scope_hash,receipt_hash));
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['equivalence_reviewed_intents','equivalence_envelopes','equivalence_artifacts','equivalence_decoded_plans','equivalence_contexts','equivalence_checks','equivalence_receipts','equivalence_request_receipts','equivalence_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I', item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION intent_equivalence_reject_mutation()', item,item); END LOOP; END $$;
COMMIT;
